local ClayPipeMaker = {}
local PRODUCTS = {
    plain_pipe = { name = "Navadna glinena pipa", clayCost = 1, time = 1, cost = 4, durability = 8, description = "Preprosta glinena pipa." },
    decorated_pipe = { name = "Okrasna pipa", clayCost = 1, time = 2, cost = 12, durability = 10, prestige = 1, description = "Z reliefom okrašena pipa." },
    long_stem_pipe = { name = "Dolgovrata pipa", clayCost = 2, time = 3, cost = 28, durability = 12, prestige = 2, description = "Dolga pipa z ozkim grlom." },
    glazed_pipe = { name = "Glazirana pipa", clayCost = 2, glassCost = 1, time = 4, cost = 60, durability = 18, prestige = 4, description = "S svetlo glazuro prekrita pipa." },
    silver_banded_pipe = { name = "S srebrom obrobljena pipa", clayCost = 2, silverCost = 1, time = 5, cost = 120, durability = 25, prestige = 8, happiness = 1, description = "Pipa s srebrnim obročkom." },
    royal_commission_pipe = { name = "Kraljevsko naročilo pipa", clayCost = 3, silverCost = 2, goldCost = 1, time = 7, cost = 320, durability = 40, prestige = 18, happiness = 3, description = "Pipa z zlato rezervo in grbom." },
}
local BUILDINGS = {
    workshop = { name = "Piparska delavnica", cost = { gold = 180, wood = 90 }, upkeep = 4, qualityBonus = 5 },
    kiln = { name = "Peč za glino", cost = { gold = 550, wood = 180, stone = 120 }, upkeep = 14, qualityBonus = 14 },
    mold_room = { name = "Kalupniča", cost = { gold = 950, wood = 220, stone = 220, silver = 20 }, upkeep = 24, qualityBonus = 20 },
    royal_pipe_atelier = { name = "Kraljevski atelje pip", cost = { gold = 2800, wood = 380, stone = 450, gold = 25 }, upkeep = 55, qualityBonus = 35, prestigeBonus = 16 },
}
ClayPipeMaker.clayStock = 22; ClayPipeMaker.glassStock = 5; ClayPipeMaker.silverStock = 4; ClayPipeMaker.goldStock = 3
ClayPipeMaker.productStock = {}; ClayPipeMaker.buildings = {}; ClayPipeMaker.maker = nil; ClayPipeMaker.activeMaking = {}; ClayPipeMaker.totalProducts = 0; ClayPipeMaker.dayTimer = 0
function ClayPipeMaker.init() ClayPipeMaker.clayStock=22; ClayPipeMaker.glassStock=5; ClayPipeMaker.silverStock=4; ClayPipeMaker.goldStock=3; ClayPipeMaker.productStock={}; ClayPipeMaker.buildings={}; ClayPipeMaker.maker=nil; ClayPipeMaker.activeMaking={}; ClayPipeMaker.totalProducts=0; ClayPipeMaker.dayTimer=0; print("[ClayPipeMaker] Royal Clay Pipe Maker System initialized (6 products, 4 buildings)") end
function ClayPipeMaker.hireMaker(n,s) s=s or math.random(35,80); local c=230+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClayPipeMaker.maker={name=n or ("Pipar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pipar najet: %s (spretnost: %d)",ClayPipeMaker.maker.name,s),"success") end; return true end
function ClayPipeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClayPipeMaker.build(id) local ok,e=ClayPipeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClayPipeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClayPipeMaker.getQualityBonus() local b=0; for _,bd in ipairs(ClayPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClayPipeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and ClayPipeMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and ClayPipeMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and ClayPipeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClayPipeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #ClayPipeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ClayPipeMaker.maker then return false,"Potreben pipar" end; return true end
function ClayPipeMaker.make(pt,qty) qty=qty or 5; local ok,e=ClayPipeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then ClayPipeMaker.clayStock=ClayPipeMaker.clayStock-d.clayCost*qty end; if d.glassCost then ClayPipeMaker.glassStock=ClayPipeMaker.glassStock-d.glassCost*qty end; if d.silverCost then ClayPipeMaker.silverStock=ClayPipeMaker.silverStock-d.silverCost*qty end; if d.goldCost then ClayPipeMaker.goldStock=ClayPipeMaker.goldStock-d.goldCost*qty end; local t=d.time; if ClayPipeMaker.maker then t=math.max(1,t-math.floor(ClayPipeMaker.maker.skill/15)) end; table.insert(ClayPipeMaker.activeMaking,{id="pipe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClayPipeMaker.completeMaking(m) local q=1.0+(ClayPipeMaker.getQualityBonus()/100); if ClayPipeMaker.maker then q=q+(ClayPipeMaker.maker.skill/200) end; q=math.min(2.0,q); ClayPipeMaker.productStock[m.productType]=(ClayPipeMaker.productStock[m.productType] or 0)+m.quantity; ClayPipeMaker.totalProducts=ClayPipeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClayPipeMaker.maker then ClayPipeMaker.maker.itemsMade=ClayPipeMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then ClayPipeMaker.maker.skill=math.min(100,ClayPipeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pipe izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function ClayPipeMaker.update(dt) if not _G.state then return end; ClayPipeMaker.dayTimer=ClayPipeMaker.dayTimer+dt; if ClayPipeMaker.dayTimer>=30 then ClayPipeMaker.dayTimer=0; for i=#ClayPipeMaker.activeMaking,1,-1 do local m=ClayPipeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClayPipeMaker.completeMaking(m); table.remove(ClayPipeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClayPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClayPipeMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClayPipeMaker.getStats() return {clayStock=ClayPipeMaker.clayStock,glassStock=ClayPipeMaker.glassStock,silverStock=ClayPipeMaker.silverStock,goldStock=ClayPipeMaker.goldStock,productStock=ClayPipeMaker.productStock,numBuildings=#ClayPipeMaker.buildings,hasMaker=ClayPipeMaker.maker~=nil,makerName=ClayPipeMaker.maker and ClayPipeMaker.maker.name or "—",makerSkill=ClayPipeMaker.maker and ClayPipeMaker.maker.skill or 0,activeMaking=#ClayPipeMaker.activeMaking,totalProducts=ClayPipeMaker.totalProducts} end
return ClayPipeMaker
